"use client";

import { useState, useEffect, useCallback, useMemo } from "react";
import { db } from "@/lib/db";
import { showToast } from "@/components/Toast";
import { formatCurrency, formatDate, todayISO } from "@/lib/helpers";
import { Wallet, Trash2, TrendingDown, Receipt } from "lucide-react";
import type { Expense } from "@/lib/database.types";
import { DT } from "@/lib/dataTableStyles";
import { confirmDialog } from "@/components/ConfirmModal";
import { logActivity } from "@/lib/activityLog";
import { useSaving } from "@/lib/useSaving";

function firstOfMonth(): string {
  const d = new Date();
  d.setDate(1);
  return d.toISOString().split("T")[0];
}

export default function ExpensePage() {
  const { saving, run } = useSaving();
  const [loading, setLoading] = useState(true);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [fromDate, setFromDate] = useState(firstOfMonth());
  const [toDate, setToDate] = useState(todayISO());

  const fetchData = useCallback(async () => {
    setLoading(true);
    const { data } = await db
      .from("expenses")
      .select("*")
      .gte("date", fromDate)
      .lte("date", toDate)
      .order("date", { ascending: false })
      .order("created_at", { ascending: false });
    if (data) setExpenses(data as Expense[]);
    setLoading(false);
  }, [fromDate, toDate]);

  useEffect(() => { void fetchData(); }, [fetchData]);

  const total = useMemo(() => expenses.reduce((s, e) => s + Number(e.amount), 0), [expenses]);

  async function handleDelete(exp: Expense) {
    const ok = await confirmDialog({
      title: "Delete expense?",
      message: `Delete this expense of ${formatCurrency(Number(exp.amount))}? The linked cash-out entry will be reversed and the amount returned to "${exp.method}".`,
      details: [exp.invoice_number ? `Invoice: ${exp.invoice_number}` : "", exp.description ? `Note: ${exp.description}` : ""].filter(Boolean).join("\n") || undefined,
      tone: "danger",
    });
    if (!ok) return;
    await run(async () => {
      // Reverse the cash impact first by removing the linked cashbook "out" entry.
      if (exp.cashbook_entry_id) {
        await db.from("cashbook").delete().eq("id", exp.cashbook_entry_id);
      }
      const { error } = await db.from("expenses").delete().eq("id", exp.id);
      if (error) { showToast(error.message, "err"); return; }
      await logActivity({
        action: "delete",
        entityType: "expense",
        entityId: exp.id,
        title: "Expense Deleted",
        subtitle: exp.invoice_number ? `${exp.invoice_number} — ${exp.description || "Expense"}` : (exp.description || "Expense"),
        amount: Number(exp.amount),
        metadata: { method: exp.method, invoice_number: exp.invoice_number },
      });
      showToast("Expense deleted", "ok");
      void fetchData();
    });
  }

  return (
    <div className="no-print animate-fade-in">
      {/* Page header */}
      <div className="mb-5">
        <h1 className="text-xl font-extrabold" style={{ color: "var(--gray-900)" }}>Expenses</h1>
        <p className="text-xs mt-0.5" style={{ color: "var(--gray-800)" }}>
          Costs recorded against walk-in invoices. Each expense is a real cash-out from a payment method.
        </p>
      </div>

      {/* KPI cards */}
      <div className="grid grid-cols-2 gap-3 mb-4 max-w-[520px]">
        <div className="bg-white rounded-[12px] border border-[var(--gray-100)] px-4 py-3" style={{ boxShadow: "var(--shadow-xs)" }}>
          <div className="flex items-center gap-2 mb-1">
            <TrendingDown size={14} style={{ color: "var(--red)" }} />
            <div className="text-[9.5px] font-bold tracking-[1.3px] uppercase" style={{ color: "var(--gray-800)" }}>Total Expenses</div>
          </div>
          <div className="text-[16px] font-extrabold font-mono" style={{ color: "var(--red)" }}>{formatCurrency(total)}</div>
        </div>
        <div className="bg-white rounded-[12px] border border-[var(--gray-100)] px-4 py-3" style={{ boxShadow: "var(--shadow-xs)" }}>
          <div className="flex items-center gap-2 mb-1">
            <Receipt size={14} style={{ color: "var(--blue-deeper)" }} />
            <div className="text-[9.5px] font-bold tracking-[1.3px] uppercase" style={{ color: "var(--gray-800)" }}>Entries</div>
          </div>
          <div className="text-[16px] font-extrabold font-mono" style={{ color: "var(--blue-deeper)" }}>{expenses.length}</div>
        </div>
      </div>

      {/* Date filter */}
      <div className="bg-white rounded-[14px] border border-[var(--gray-100)] p-4 mb-4" style={{ boxShadow: "var(--shadow-sm)" }}>
        <div className="flex flex-wrap gap-3 items-end">
          <div className="flex flex-col gap-1">
            <label className="text-[9.5px] font-bold tracking-[1.2px] uppercase" style={{ color: "var(--blue-deeper)" }}>From</label>
            <input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)}
              className="border border-[var(--gray-200)] rounded-[8px] px-3 py-2 text-[13px] outline-none bg-white focus:border-[var(--blue)]" />
          </div>
          <div className="flex flex-col gap-1">
            <label className="text-[9.5px] font-bold tracking-[1.2px] uppercase" style={{ color: "var(--blue-deeper)" }}>To</label>
            <input type="date" value={toDate} onChange={(e) => setToDate(e.target.value)}
              className="border border-[var(--gray-200)] rounded-[8px] px-3 py-2 text-[13px] outline-none bg-white focus:border-[var(--blue)]" />
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-[14px] border border-[var(--gray-100)] overflow-hidden" style={{ boxShadow: "var(--shadow-sm)" }}>
        {loading ? (
          <div className="text-center py-10 text-[13px]" style={{ color: "var(--gray-800)" }}>Loading…</div>
        ) : expenses.length === 0 ? (
          <div className="py-14 text-center">
            <Wallet size={32} className="mx-auto mb-2" style={{ color: "var(--gray-200)" }} />
            <p className="text-[13px] font-medium" style={{ color: "var(--gray-800)" }}>No expenses in this period.</p>
            <p className="text-[12px] mt-1" style={{ color: "var(--gray-600)" }}>
              Tick &ldquo;Add expense for this invoice&rdquo; when creating a walk-in invoice to record one.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className={`${DT.table} min-w-[820px]`}>
              <thead>
                <tr>
                  {["#", "Date", "Invoice #", "Description", "Method", "Created By", "Amount", ""].map((h) => {
                    const right = h === "Amount";
                    return <th key={h} className={`${DT.thDense} ${right ? "text-right" : "text-left"}`} style={DT.thStyle}>{h}</th>;
                  })}
                </tr>
              </thead>
              <tbody>
                {expenses.map((exp, idx) => (
                  <tr key={exp.id} className={DT.row}>
                    <td className={`${DT.tdDense} ${DT.cellBody}`} style={{ color: "var(--gray-800)" }}>{idx + 1}</td>
                    <td className={`${DT.tdDense} ${DT.cellBody} whitespace-nowrap`} style={{ color: "var(--gray-900)" }}>{formatDate(exp.date)}</td>
                    <td className={`${DT.tdDense} ${DT.cellBody} font-mono`} style={{ color: "var(--blue-deeper)" }}>{exp.invoice_number || "—"}</td>
                    <td className={`${DT.tdDense} ${DT.cellPrimary}`} style={{ color: "var(--gray-900)" }}>{exp.description || "—"}</td>
                    <td className={`${DT.tdDense}`}>
                      <span className="px-2 py-0.5 rounded-full text-[10.5px] font-semibold" style={{ background: "var(--gray-100)", color: "var(--gray-900)" }}>{exp.method}</span>
                    </td>
                    <td className={`${DT.tdDense} ${DT.cellBody}`} style={{ color: "var(--gray-800)" }}>{exp.created_by_name || "—"}</td>
                    <td className={`${DT.tdDense} font-mono text-right font-extrabold text-[15px]`} style={{ color: "var(--red)" }}>{formatCurrency(exp.amount)}</td>
                    <td className={`${DT.tdDense} text-right`}>
                      <button
                        type="button"
                        onClick={() => void handleDelete(exp)}
                        disabled={saving}
                        title="Delete expense"
                        className="inline-flex items-center justify-center w-8 h-8 rounded-[8px] border-none bg-transparent cursor-pointer transition-all hover:bg-[var(--red-light)] disabled:opacity-50"
                        style={{ color: "var(--red)" }}
                      >
                        <Trash2 size={15} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot>
                <tr style={{ background: "var(--gray-50)" }}>
                  <td colSpan={6} className={`${DT.tdDense} text-[13.5px] font-bold border-t-2 border-[var(--gray-200)]`} style={{ color: "var(--gray-700)" }}>
                    Total — {expenses.length} {expenses.length !== 1 ? "entries" : "entry"}
                  </td>
                  <td className={`${DT.tdDense} font-mono text-right text-[15px] font-extrabold border-t-2 border-[var(--gray-200)]`} style={{ color: "var(--red)" }}>{formatCurrency(total)}</td>
                  <td className="border-t-2 border-[var(--gray-200)]" />
                </tr>
              </tfoot>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}
